makeSlots();updateHealth();
function openBag(){panelOpen=!panelOpen;document.getElementById('panel').classList.toggle('open',panelOpen);refreshBag()}
function refreshBag(){const el=document.getElementById('inventory');const rows=[['Дерево','wood','🪵'],['Земля','dirt','🟫'],['Камень','stone','🪨'],['Медная руда','copper','🟠'],['Слизь','gel','🟢'],['Верстак','workbench','🛠']];el.innerHTML=rows.map(([name,id,icon])=>`<div class="craftrow"><span>${icon} ${name}</span><b>${inv[id]||0}</b></div>`).join('')+`<div class="craftrow"><span>🪚 Верстак <small>(10 дерева)</small></span><button id="craftBench" ${inv.wood<10||inv.workbench?'disabled':''}>${inv.workbench?'СОЗДАН':'СОЗДАТЬ'}</button></div><div class="craftrow"><span>🗡 Железный клинок <small>(5 камня, 3 меди)</small></span><button id="craftSword" ${inv.stone<5||inv.copper<3?'disabled':''}>СОЗДАТЬ</button></div>`;
const bench=document.getElementById('craftBench');if(bench)bench.onclick=()=>{if(inv.wood>=10&&!inv.workbench){inv.wood-=10;inv.workbench=1;toast('Верстак готов!');refreshBag();makeSlots()}};const sword=document.getElementById('craftSword');if(sword)sword.onclick=()=>{if(inv.stone>=5&&inv.copper>=3){inv.stone-=5;inv.copper-=3;items[1].icon='🗡️';items[1].name='Клинок';toast('Клинок выкован!');refreshBag();makeSlots()}}}
document.getElementById('close').onclick=openBag();addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if(k==='e'){openBag();e.preventDefault()}if(k==='escape'&&panelOpen)openBag();if(k>='1'&&k<='5'){selected=+k-1;makeSlots()}if(k===' '||k.startsWith('arrow'))e.preventDefault()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.getElementById('hotbar').addEventListener('click',e=>{const el=e.target.closest('.slot');if(el){selected=+el.dataset.slot;makeSlots()}});
canvas.addEventListener('mousemove',e=>{mouse.x=e.clientX;mouse.y=e.clientY});canvas.addEventListener('mousedown',e=>{if(e.button===0)mouse.left=true;if(e.button===2)mouse.right=true});addEventListener('mouseup',e=>{if(e.button===0)mouse.left=false;if(e.button===2)mouse.right=false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
for(const btn of document.querySelectorAll('.touch button')){const key=btn.dataset.key;btn.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true});for(const ev of ['pointerup','pointercancel','pointerleave'])btn.addEventListener(ev,()=>keys[key]=false)}
function targetTile(){return{x:Math.floor((mouse.x+camX)/TILE),y:Math.floor((mouse.y+camY)/TILE)}}
function collect(id){if(id==='grass'||id==='dirt')inv.dirt++;else if(id==='wood')inv.wood++;else if(id==='stone')inv.stone++;else if(id==='copper')inv.copper++;else if(id==='leaf'&&Math.random()<.25)inv.wood++;makeSlots();if(panelOpen)refreshBag()}
function damagePlayer(amount){if(player.invuln>0)return;player.hp=Math.max(0,player.hp-amount);player.invuln=1.1;player.vy=-230;updateHealth();if(player.hp<=0){toast('Ты пал… но приключение продолжается');setTimeout(()=>{player.hp=5;player.x=15*TILE;player.y=surfaceAt(15)*TILE-player.h-2;player.vx=player.vy=0;updateHealth()},1100)}}
function update(dt){time+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.getElementById('toast').classList.remove('show')}
const mins=Math.floor((time%180)/180*24*60+8*60),hour=Math.floor(mins/60)%24,minute=mins%60;document.getElementById('clock').textContent=String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0');document.getElementById('day').textContent=String(1+Math.floor(time/180)).padStart(2,'0');const night=hour<6||hour>19;
if(panelOpen)return;
const left=keys.a||keys.arrowleft,right=keys.d||keys.arrowright;let dir=(right?1:0)-(left?1:0);if(dir){player.vx+=dir*1000*dt;player.facing=dir}else player.vx*=Math.pow(.001,dt);player.vx=Math.max(-225,Math.min(225,player.vx));if((keys[' ']||keys.w||keys.arrowup||keys.jump)&&player.ground){player.vy=-420;player.ground=false;keys.jump=false}
player.vy=Math.min(700,player.vy+1000*dt);moveBody(player,dt);player.invuln=Math.max(0,player.invuln-dt);player.attack=Math.max(0,player.attack-dt);player.stamina=Math.min(100,player.stamina+dt*13);
if(mouse.left||keys.mine||keys.attack){const near=enemies.find(e=>e.alive&&Math.abs(e.x+e.w/2-(player.x+player.w/2))<60&&Math.abs(e.y-player.y)<54);if(near&&player.attack<=0){near.hp--;near.vx=player.facing*190;near.vy=-145;player.attack=.32;addParticle(near.x+near.w/2,near.y,'#fff0a0',7);if(near.hp<=0){near.alive=false;inv.gel+=ri(1,3);makeSlots();toast('Слизь побеждена · + слизь')}}else if(mouse.left){const t=targetTile(),dx=(t.x*TILE+16)-(player.x+player.w/2),dy=(t.y*TILE+16)-(player.y+player.h/2);if(Math.hypot(dx,dy)<150){const id=tile(t.x,t.y);if(id&&id!=='cave'){if(!mineTarget||mineTarget.x!==t.x||mineTarget.y!==t.y){mineTarget=t;mineTime=0}mineTime+=dt*(id==='stone'||id==='copper'?.65:1.6);if(mineTime>(id==='stone'||id==='copper'?.8:.48)){collect(id);world[t.x][t.y]=null;addParticle(t.x*TILE+16,t.y*TILE+16,id==='stone'?'#9ca8a3':'#8cbd83',7);mineTime=0;mineTarget=null}}else{mineTarget=null;mineTime=0}}}else if(keys.attack&&player.attack<=0){player.attack=.32}}
if(mouse.right){const t=targetTile(),item=items[selected];if(item.type==='block'&&inv[item.id]>0&&Math.hypot(t.x*TILE+16-player.x, t.y*TILE+16-player.y)<155&&!tile(t.x,t.y)&&!(t.x*TILE<player.x+player.w&&t.x*TILE+TILE>player.x&&t.y*TILE<player.y+player.h&&t.y*TILE+TILE>player.y)){world[t.x][t.y]=item.id;inv[item.id]--;makeSlots();mouse.right=false}}
for(const e of enemies){if(!e.alive)continue;e.hop-=dt;if(e.hop<=0&&Math.abs(player.x-e.x)<260){e.vx=Math.sign(player.x-e.x)*rand(45,90);e.vy=-rand(170,240);e.hop=rand(.8,1.8)}e.vy+=850*dt;e.x+=e.vx*dt;e.y+=e.vy*dt;e.vx*=Math.pow(.08,dt);const floor=surfaceAt(Math.max(0,Math.min(W-1,Math.floor((e.x+e.w/2)/TILE))))*TILE-e.h;if(e.y>floor){e.y=floor;e.vy=0}if(e.x<player.x+player.w&&e.x+e.w>player.x&&e.y<player.y+player.h&&e.y+e.h>player.y)damagePlayer(1)}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=400*dt;if(p.life<=0)particles.splice(i,1)}
camX=Math.max(0,Math.min(W*TILE-vw,player.x+player.w/2-vw/2));camY=Math.max(0,Math.min(H*TILE-vh,player.y+player.h/2-vh*.53));if(camY>H*TILE-vh)camY=H*TILE-vh;
}
function moveBody(o,dt){o.x+=o.vx*dt;let x1=Math.floor(o.x/TILE),x2=Math.floor((o.x+o.w-1)/TILE),y1=Math.floor(o.y/TILE),y2=Math.floor((o.y+o.h-1)/TILE);for(let y=y1;y<=y2;y++)for(let x=x1;x<=x2;x++)if(solid(tile(x,y))){if(o.vx>0)o.x=x*TILE-o.w;else if(o.vx<0)o.x=(x+1)*TILE;o.vx=0}o.y+=o.vy*dt;o.ground=false;x1=Math.floor(o.x/TILE);x2=Math.floor((o.x+o.w-1)/TILE);y1=Math.floor(o.y/TILE);y2=Math.floor((o.y+o.h-1)/TILE);for(let y=y1;y<=y2;y++)for(let x=x1;x<=x2;x++)if(solid(tile(x,y))){if(o.vy>0){o.y=y*TILE-o.h;o.ground=true}else if(o.vy<0)o.y=(y+1)*TILE;o.vy=0}}

